%% ========================================================================
% d_check_partial_uncertainty_dependence.m
% PARTIAL CORRELATION UNCERTAINTY + RESIDUAL ANNUAL-LAG-1 DIAGNOSTIC
% MATLAB R2021a | Place in Data/06_Climate_Mode_Sensitivity/
%
% INPUTS (same folder, generated by scripts b and c):
%   seasonal_partial_correlation_results.mat
%   seasonal_partial_robustness_results.csv
% OUTPUTS (same folder):
%   partial_uncertainty_dependence_summary.csv  (24 region-season-control rows)
%   partial_residual_adjacent_year_pairs.csv
%
% This script checks the existing partial coefficients and reports lag-1
% dependence of X|Z and Y|Z residuals, and index Z, for consecutive years.
% It does NOT re-run permutations or change p-values/qFDR.
%
% WARNING: With only 9-10 seasons, annual lag-1 is a weak diagnostic.
% Small lag-1 does NOT demonstrate exchangeability. The conditional
% Freedman-Lane-style permutation still assumes adequate exchangeability.
%% ========================================================================
clc;
clear;
this_script = mfilename('fullpath');
if isempty(this_script), error('Save this as an .m script first.'); end
folder_out = fileparts(this_script);
mat_file = fullfile(folder_out,'seasonal_partial_correlation_results.mat');
csv_file = fullfile(folder_out,'seasonal_partial_robustness_results.csv');
if ~isfile(mat_file) || ~isfile(csv_file)
    error('Required files missing; run b and c in this folder first.');
end
D = load(mat_file,'Data');
T = readtable(csv_file);
if ~isfield(D,'Data') || height(T)~=12
    error('Unexpected MAT structure or robustness table.');
end

Region = cell(24,1); Season = cell(24,1); Control = cell(24,1);
N = NaN(24,1); Parametric_df = NaN(24,1);
Original_r = NaN(24,1); Partial_r = NaN(24,1);
CI95_lower = NaN(24,1); CI95_upper = NaN(24,1);
p_permutation = NaN(24,1); q_FDR = NaN(24,1);
LOYO_min_r = NaN(24,1); LOYO_max_r = NaN(24,1);
LOYO_sign_percent = NaN(24,1);
N_adjacent_pairs = NaN(24,1);
Index_annual_lag1 = NaN(24,1);
Residual_SST_lag1 = NaN(24,1);
Residual_Rain_lag1 = NaN(24,1);
FDR_interpretation = cell(24,1);

P_Region = cell(0,1); P_Season = cell(0,1);
P_Control = cell(0,1); Year_t = zeros(0,1);
Year_t_plus1 = zeros(0,1);
Index_t = zeros(0,1); Index_t_plus1 = zeros(0,1);
SST_resid_t = zeros(0,1); SST_resid_t_plus1 = zeros(0,1);
Rain_resid_t = zeros(0,1); Rain_resid_t_plus1 = zeros(0,1);

regions = {'Flores','Sumba','Timor'};
seasons = {'DJF','MAM','JJA','SON'};
controls = {'Nino34','DMI'};
row = 0;
for ir=1:3
    reg = regions{ir};
    for is=1:4
        ss = seasons{is};
        idx_result = strcmp(string(T.Region),reg) & ...
                     strcmp(string(T.Season),ss);
        if sum(idx_result)~=1
            error('Missing or duplicate result: %s %s.',reg,ss);
        end
        Q = D.Data.(reg).(ss);
        xx = double(Q.SST(:)); yy = double(Q.RAIN(:));
        z_n = double(Q.Nino34(:)); z_d = double(Q.DMI(:));
        years = double(Q.Year(:));
        valid = isfinite(xx)&isfinite(yy)&isfinite(z_n)&isfinite(z_d);
        xx=xx(valid); yy=yy(valid); z_n=z_n(valid); z_d=z_d(valid);
        years=years(valid); n=numel(years);
        if n < 6 || T.N(idx_result)~=n || any(diff(years)<=0)
            error('Unexpected years/sample size for %s %s.',reg,ss);
        end
        r_unadjusted = corr(xx,yy,'Type','Pearson');
        if abs(r_unadjusted-T.Original_r(idx_result))>1e-8
            error('Original r QC mismatch: %s %s.',reg,ss);
        end
        for ic=1:2
            row = row+1; control = controls{ic};
            if ic==1, zz=z_n; else, zz=z_d; end
            A = [ones(n,1),zz];
            if rank(A)<2
                error('Index regression rank-deficient for %s %s %s.',reg,ss,control);
            end
            rx = xx-A*(A\xx);
            ry = yy-A*(A\yy);
            r_partial = corr(rx,ry,'Type','Pearson');
            if ic==1
                r_expected=T.Partial_Nino_r(idx_result);
                ci_l=T.Nino_CI_low(idx_result);
                ci_u=T.Nino_CI_high(idx_result);
                pv=T.Nino_p_perm(idx_result); qv=T.Nino_q_FDR(idx_result);
                lmin=T.Nino_LOYO_min(idx_result);
                lmax=T.Nino_LOYO_max(idx_result);
                sgn=T.Nino_LOYO_sign_percent(idx_result);
            else
                r_expected=T.Partial_DMI_r(idx_result);
                ci_l=T.DMI_CI_low(idx_result);
                ci_u=T.DMI_CI_high(idx_result);
                pv=T.DMI_p_perm(idx_result); qv=T.DMI_q_FDR(idx_result);
                lmin=T.DMI_LOYO_min(idx_result);
                lmax=T.DMI_LOYO_max(idx_result);
                sgn=T.DMI_LOYO_sign_percent(idx_result);
            end
            if abs(r_expected-r_partial)>1e-8
                error('Partial r QC mismatch: %s %s %s.',reg,ss,control);
            end
            Region{row}=reg; Season{row}=ss; Control{row}=control;
            N(row)=n; Parametric_df(row)=n-3;
            Original_r(row)=r_unadjusted; Partial_r(row)=r_partial;
            CI95_lower(row)=ci_l; CI95_upper(row)=ci_u;
            p_permutation(row)=pv; q_FDR(row)=qv;
            LOYO_min_r(row)=lmin; LOYO_max_r(row)=lmax;
            LOYO_sign_percent(row)=sgn;
            if qv<0.05
                FDR_interpretation{row}='FDR-retained (q<0.05)';
            elseif qv<0.10
                FDR_interpretation{row}='Suggestive only (0.05<=q<0.10)';
            else
                FDR_interpretation{row}='Not retained (q>=0.10)';
            end

            adjacent = find(diff(years)==1);
            np=numel(adjacent); N_adjacent_pairs(row)=np;
            if np>=3
                i1=adjacent; i2=adjacent+1;
                if std(zz(i1))>0 && std(zz(i2))>0
                    Index_annual_lag1(row)=corr(zz(i1),zz(i2),'Type','Pearson');
                end
                if std(rx(i1))>0 && std(rx(i2))>0
                    Residual_SST_lag1(row)=corr(rx(i1),rx(i2),'Type','Pearson');
                end
                if std(ry(i1))>0 && std(ry(i2))>0
                    Residual_Rain_lag1(row)=corr(ry(i1),ry(i2),'Type','Pearson');
                end
            end
            for j=1:np
                k=adjacent(j);
                P_Region{end+1,1}=reg; %#ok<SAGROW>
                P_Season{end+1,1}=ss; %#ok<SAGROW>
                P_Control{end+1,1}=control; %#ok<SAGROW>
                Year_t(end+1,1)=years(k); %#ok<SAGROW>
                Year_t_plus1(end+1,1)=years(k+1); %#ok<SAGROW>
                Index_t(end+1,1)=zz(k); %#ok<SAGROW>
                Index_t_plus1(end+1,1)=zz(k+1); %#ok<SAGROW>
                SST_resid_t(end+1,1)=rx(k); %#ok<SAGROW>
                SST_resid_t_plus1(end+1,1)=rx(k+1); %#ok<SAGROW>
                Rain_resid_t(end+1,1)=ry(k); %#ok<SAGROW>
                Rain_resid_t_plus1(end+1,1)=ry(k+1); %#ok<SAGROW>
            end
        end
    end
end

Summary = table(Region,Season,Control,N,Parametric_df,Original_r, ...
    Partial_r,CI95_lower,CI95_upper,p_permutation,q_FDR, ...
    LOYO_min_r,LOYO_max_r,LOYO_sign_percent,N_adjacent_pairs, ...
    Index_annual_lag1,Residual_SST_lag1,Residual_Rain_lag1, ...
    FDR_interpretation);
PairTable = table(P_Region,P_Season,P_Control,Year_t,Year_t_plus1, ...
    Index_t,Index_t_plus1,SST_resid_t,SST_resid_t_plus1, ...
    Rain_resid_t,Rain_resid_t_plus1, ...
    'VariableNames',{'Region','Season','Control','Year_t','Year_t_plus1', ...
    'Index_t','Index_t_plus1','SST_resid_t','SST_resid_t_plus1', ...
    'Rain_resid_t','Rain_resid_t_plus1'});
writetable(Summary,fullfile(folder_out,'partial_uncertainty_dependence_summary.csv'));
writetable(PairTable,fullfile(folder_out,'partial_residual_adjacent_year_pairs.csv'));

fprintf('\n===== PARTIAL UNCERTAINTY + ANNUAL RESIDUAL DEPENDENCE QC =====\n');
fprintf('24 tests (3 regions x 4 seasons x 2 controls).\n');
fprintf('FDR q<0.05: Nino=%d/12, DMI=%d/12.\n', ...
    sum(q_FDR(strcmp(Control,'Nino34'))<0.05), ...
    sum(q_FDR(strcmp(Control,'DMI'))<0.05));
fprintf('Region   Season  Control  n  df    r_partial   q_FDR  residRain_rho1\n');
for k=1:24
    fprintf('%-8s %-4s   %-6s  %2d   %2d    %+0.3f     %0.4f     %+0.3f\n', ...
        Region{k},Season{k},Control{k},N(k),Parametric_df(k), ...
        Partial_r(k),q_FDR(k),Residual_Rain_lag1(k));
end
fprintf('Saved: partial_uncertainty_dependence_summary.csv\n');
fprintf('       partial_residual_adjacent_year_pairs.csv\n');
fprintf('CAUTION: lag-1 residual checks are descriptive; they cannot prove exchangeability.\n');
fprintf('Fisher-z 95%% intervals are approximate, not multiple-testing adjusted.\n');
